package com.opensocket.aievent.core.iam.api.response;import com.opensocket.aievent.core.iam.rbac.domain.PrincipalRoleBinding;import java.time.Instant;
public record RoleBindingResponse(String bindingId,String principalType,String principalId,String roleId,String scopeType,String scopeId,Instant effectiveAt,Instant expiresAt,String status,long version){public static RoleBindingResponse from(PrincipalRoleBinding b){return new RoleBindingResponse(b.bindingId(),b.principal().principalType().name(),b.principal().principalId(),b.roleId().value(),b.scope().type().name(),b.scope().scopeId(),b.effectiveAt(),b.expiresAt(),b.status().name(),b.version());}}
